-- Replace the shipped placeholder without overwriting authored policy copy.
UPDATE content
SET draft = CASE WHEN draft IS NOT NULL AND json_extract(draft, '$.description.en') = 'The approved CCI privacy policy will be published here. Enquiry collection remains unavailable until it has been approved.' AND json_array_length(draft, '$.sections') = 0 THEN json_set(draft, '$.description.en', 'How Click Cross Initiative handles information you share through this website, including contact form enquiries.', '$.sections', json('[{"id":"scope","heading":{"en":"About this notice","my":""},"body":{"en":"Click Cross Initiative (CCI) operates this organization website. This notice explains what happens when you browse the site or contact CCI. Other websites and platforms linked here, including learning and social media services, have their own privacy notices.","my":""},"image":"","cta":{"en":"","my":""},"href":"","visible":true,"order":0},{"id":"enquiries","heading":{"en":"What we collect when you contact us","my":""},"body":{"en":"The contact form asks for your name, email address, subject, and message. We record when the enquiry arrives. Authorized staff can add internal notes and update the enquiry status. Please leave out passwords, payment details, identity documents, and sensitive evidence.","my":""},"image":"","cta":{"en":"","my":""},"href":"","visible":true,"order":1},{"id":"use","heading":{"en":"How we use your enquiry","my":""},"body":{"en":"We use your message to review your request, follow up with you, and keep a record of how it was handled. We use technical information such as your IP address to limit repeated submissions and reduce abuse.","my":""},"image":"","cta":{"en":"","my":""},"href":"","visible":true,"order":2},{"id":"access","heading":{"en":"Who can access your information","my":""},"body":{"en":"Enquiries are stored in the website''s staff inbox. Access is restricted to authorized staff. The services that host the website and support staff sign-in process information as part of providing those services. When you follow an external link, the destination handles information under its own practices.","my":""},"image":"","cta":{"en":"","my":""},"href":"","visible":true,"order":3},{"id":"retention","heading":{"en":"How long information is kept","my":""},"body":{"en":"Enquiries are kept in the inbox for follow-up and recordkeeping. Closing an enquiry changes its status and does not automatically delete it. If you would like us to review whether we can delete a record, contact us using the details below.","my":""},"image":"","cta":{"en":"","my":""},"href":"","visible":true,"order":4},{"id":"choices","heading":{"en":"Questions and requests","my":""},"body":{"en":"Use Contact Us to ask how we have handled your enquiry or to request access, a correction, or deletion. Include enough information for us to identify your enquiry, such as the email address used and the approximate date. We may need to verify the request before sharing or changing information.","my":""},"image":"","cta":{"en":"Contact us","my":""},"href":"/en/contact","visible":true,"order":5}]')) ELSE draft END,
    published = CASE WHEN published IS NOT NULL AND json_extract(published, '$.description.en') = 'The approved CCI privacy policy will be published here. Enquiry collection remains unavailable until it has been approved.' AND json_array_length(published, '$.sections') = 0 THEN json_set(published, '$.description.en', 'How Click Cross Initiative handles information you share through this website, including contact form enquiries.', '$.sections', json('[{"id":"scope","heading":{"en":"About this notice","my":""},"body":{"en":"Click Cross Initiative (CCI) operates this organization website. This notice explains what happens when you browse the site or contact CCI. Other websites and platforms linked here, including learning and social media services, have their own privacy notices.","my":""},"image":"","cta":{"en":"","my":""},"href":"","visible":true,"order":0},{"id":"enquiries","heading":{"en":"What we collect when you contact us","my":""},"body":{"en":"The contact form asks for your name, email address, subject, and message. We record when the enquiry arrives. Authorized staff can add internal notes and update the enquiry status. Please leave out passwords, payment details, identity documents, and sensitive evidence.","my":""},"image":"","cta":{"en":"","my":""},"href":"","visible":true,"order":1},{"id":"use","heading":{"en":"How we use your enquiry","my":""},"body":{"en":"We use your message to review your request, follow up with you, and keep a record of how it was handled. We use technical information such as your IP address to limit repeated submissions and reduce abuse.","my":""},"image":"","cta":{"en":"","my":""},"href":"","visible":true,"order":2},{"id":"access","heading":{"en":"Who can access your information","my":""},"body":{"en":"Enquiries are stored in the website''s staff inbox. Access is restricted to authorized staff. The services that host the website and support staff sign-in process information as part of providing those services. When you follow an external link, the destination handles information under its own practices.","my":""},"image":"","cta":{"en":"","my":""},"href":"","visible":true,"order":3},{"id":"retention","heading":{"en":"How long information is kept","my":""},"body":{"en":"Enquiries are kept in the inbox for follow-up and recordkeeping. Closing an enquiry changes its status and does not automatically delete it. If you would like us to review whether we can delete a record, contact us using the details below.","my":""},"image":"","cta":{"en":"","my":""},"href":"","visible":true,"order":4},{"id":"choices","heading":{"en":"Questions and requests","my":""},"body":{"en":"Use Contact Us to ask how we have handled your enquiry or to request access, a correction, or deletion. Include enough information for us to identify your enquiry, such as the email address used and the approximate date. We may need to verify the request before sharing or changing information.","my":""},"image":"","cta":{"en":"Contact us","my":""},"href":"/en/contact","visible":true,"order":5}]')) ELSE published END,
    version = version + 1,
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
WHERE id = 'privacy';
--> statement-breakpoint
-- Open enquiry intake and add the confirmed Facebook link to existing sites.
UPDATE content
SET draft = json_set(CASE WHEN json_type(draft, '$.socialLinks.facebook') IS NULL THEN json_set(draft, '$.socialLinks.facebook', 'https://www.facebook.com/clickcrossinitiative/') ELSE draft END, '$.privacyApproved', json('true')),
    published = json_set(CASE WHEN json_type(published, '$.socialLinks.facebook') IS NULL THEN json_set(published, '$.socialLinks.facebook', 'https://www.facebook.com/clickcrossinitiative/') ELSE published END, '$.privacyApproved', json('true')),
    version = version + 1,
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
WHERE id = 'site'
  AND EXISTS (SELECT 1 FROM content WHERE id = 'privacy' AND published IS NOT NULL);
